interface.definition:
a!localVariables(

  {
    {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  char(10),
                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: "DPP Bulk User Creation",
                    color: "#386087",
                    size: "MEDIUM_PLUS",
                    style: "STRONG"
                  ),
                  char(10),
                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: "Used to create users in bulk",
                    color: "SECONDARY",
                    size: "SMALL"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                contents: {
                  #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_fileUploadField_v1"(
                            label: "File Upload",
                            labelPosition: "ABOVE",
                            helpTooltip: "Please upload the file in the .xlsx or .xls format only",
                            target: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12334339",
                            fileNames: fv!file.name,
                            maxSelections: 1,
                            value: ri!uploadedFile,
                            saveInto: {
                              ri!uploadedFile,
                              if(
                                #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(ri!uploadedFile),
                                a!save(ri!nullData, false()),
                                a!save(ri!nullData, ri!nullData)
                              )
                            },
                            required: true(),
                            requiredMessage: "Please Upload the exact User creation File",
                            validations: {
                              if(
                                or(
                                  fv!files.extension = "xlsx",
                                  fv!files.extension = "xls"
                                ),
                                {},
                                "Please Uplaod the file in the correct Format"
                              )
                            }
                          ),
                          #"SYSTEM_SYSRULES_sideBySideLayout"(
                            items: {
                              #"SYSTEM_SYSRULES_sideBySideItem"(
                                item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  value: {
                                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                                      text: "  Please download the Excel template from the below downloadable link.",
                                      size: "SMALL",
                                      style: "STRONG"
                                    )
                                  }
                                )
                              )
                            }
                          ),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            value: {
                              #"SYSTEM_SYSRULES_richTextIcon"(
                                icon: "download",
                                caption: "Please click here to download the Excel Template",
                                link: #"SYSTEM_SYSRULES_documentDownloadLink"(label: "Bulk User creation Template"),
                                linkStyle: "STANDALONE"
                              ),
                              char(9),
                              #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: "Bulk user creation template",
                                link: #"SYSTEM_SYSRULES_documentDownloadLink"(
                                  label: "Bulk user Creation Template",
                                  document: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12334360"
                                ),
                                linkStyle: "STANDALONE"
                              )
                            },
                            tooltip: "",
                            align: "LEFT",
                            accessibilityText: "Please download the Excel template to proceed"
                          ),

                        }
                      ),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_sectionLayout_v1"(),
                          #"SYSTEM_SYSRULES_sectionLayout_v1"(),
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: {
                              char(9),
                              #"SYSTEM_SYSRULES_richTextIcon"(
                                icon: "warning",
                                color: "#386087",
                                size: "MEDIUM_PLUS"
                              ),
                              char(9),
                              #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: "No Data available in the file. Please reupload."
                              )
                            },
                            showWhen: ri!nullData = true()
                          )
                        }
                      ),

                    }
                  )
                }
              ),

              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                label: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12334438"[10],
                contents: {
                  #"SYSTEM_SYSRULES_pickerFieldGroups"(
                    label: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12334438"[11],
                    labelPosition: "ADJACENT",
                    instructions: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12334438"[12],
                    maxSelections: 10,
                    groupFilter: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219526",
                    value: ri!groups,
                    saveinto: {
                      ri!groups,
                      a!save(ri!groups, #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3076078"(ri!groups))
                    }
                  )
                }
              ),
              #"SYSTEM_SYSRULES_ButtonLayout"(
                primaryButtons: {
                  #"SYSTEM_SYSRULES_ButtonWidget"(
                    label: "NEXT",
                    value: ri!uploadedFile,
                    saveInto: {
                      ri!uploadedFile,
                      a!save(ri!buttonValue, "NEXT"),

                    },
                    submit: true(),
                    style: "PRIMARY",
                    disabled: {
                      #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(ri!groups),
                      #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219631"(ri!uploadedFile)
                    },
                    confirmMessage: "Are you sure you want to Submit ?"
                  )
                },
                secondaryButtons: {
                  #"SYSTEM_SYSRULES_ButtonWidget"(
                    label: "CANCEL",
                    value: "CANCEL",
                    saveInto: { a!save(ri!buttonValue, "CANCEL") },
                    submit: true(),
                    style: "PRIMARY",
                    validate: false,
                    confirmMessage: "Are you sure you want to cancel ?"
                  )
                }
              )
            }
          )
        }
      )
    },

  }
)
